mapper.select:
SELECT id, user_id, type, points, balance_after, biz_type, biz_id,
       description, expired_time, create_time
FROM stellar_points_record
WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM stellar_points_record
WHERE user_id = #{userId}
  AND biz_type = #{bizType}
  AND DATE(create_time) = #{today}

SELECT id, user_id, type, points, balance_after, biz_type, biz_id,
       description, expired_time, create_time
FROM stellar_points_record
WHERE user_id = #{userId}
  AND biz_type = #{bizType}
  AND biz_id = #{bizId}
  AND type = 1
